// ---- GLResLoader file-backed (curado 2026-09-22, reemplaza stubs NULL) ----
// El .so NO usa AAssetManager (0 hits); pide assets por estos callbacks Java.
// Estructura real en Vita (ux0_data/gtracingmotoracademyhd/): res/, assets/,
// GTRacing/ (ex-/sdcard). Orden de resolucion = Java: res/assets y luego sdcard.
// Sin DATA_PATH el define viene de CMake; fallback a la ruta literal.
#ifndef DATA_PATH
#define DATA_PATH "ux0:data/gtracingmotoracademyhd/"
#endif

static const char *glres_cstr(jobject name) {
    if (!name) return NULL;
    return jni->GetStringUTFChars(&jni, (jstring)name, NULL);
}

static void glres_release(jobject name, const char *s) {
    if (name && s) jni->ReleaseStringUTFChars(&jni, (jstring)name, s);
}

// Normaliza "./x" / ".//x" de Java y prueba candidatos bajo DATA_PATH.
// Devuelve 1 y llena `out` con la primera ruta existente.
static int glres_resolve(const char *name, char *out, size_t out_size) {
    if (!name || !*name) return 0;
    while (name[0] == '.' && name[1] == '/') name += 2;
    while (*name == ' ') name++;

    // Ruta sdcard absoluta -> GTRacing/ (mismo mapa que io.c).
    const char *sd = "/sdcard/gameloft/games/GTRacing/";
    if (strncmp(name, sd, strlen(sd)) == 0) {
        const char *rest = name + strlen(sd);
        while (*rest == '/') rest++;
        snprintf(out, out_size, DATA_PATH"GTRacing/%s", rest);
        if (access(out, R_OK) == 0) return 1;
        return 0;
    }

    char tmp[256];
    snprintf(tmp, sizeof(tmp), "%s", name);
    // (0) tal cual bajo DATA_PATH (por si el caller ya trae assets/... o res/...)
    // (1) assets/  (2) res/
    char c0[256], c1[256], c2[256];
    snprintf(c0, sizeof(c0), DATA_PATH"%s", tmp);
    snprintf(c1, sizeof(c1), DATA_PATH"assets/%s", tmp);
    snprintf(c2, sizeof(c2), DATA_PATH"res/%s", tmp);
    const char *cands[3] = { c0, c1, c2 };
    for (int i = 0; i < 3; i++) {
        if (access(cands[i], R_OK) == 0) {
            snprintf(out, out_size, "%s", cands[i]);
            return 1;
        }
    }
    return 0;
}

static long glres_filesize(const char *path) {
    struct stat st;
    if (stat(path, &st) != 0) return -1;
    return (long)st.st_size;
}

// Lee un archivo completo a un jbyteArray (tramos de 64KB, como arriba).
static jbyteArray glres_read_whole(const char *path) {
    long size = glres_filesize(path);
    FILE *f = size > 0 ? fopen(path, "rb") : NULL;
    if (!f) return NULL;
    jbyteArray arr = jni->NewByteArray(&jni, (jsize)size);
    if (arr) {
        static jbyte chunk[65536];
        jsize done = 0;
        while (done < (jsize)size) {
            jsize want = (jsize)size - done > (jsize)sizeof(chunk) ? (jsize)sizeof(chunk) : (jsize)size - done;
            size_t got = fread(chunk, 1, (size_t)want, f);
            if (got == 0) break;
            jni->SetByteArrayRegion(&jni, arr, done, (jsize)got, chunk);
            done += (jsize)got;
        }
    }
    fclose(f);
    return arr;
}

