jbyteArray stub_GLResLoader_getResourceBytes_45(jmethodID id, va_list args) {
    jobject jname = (jobject) va_arg(args, jobject);
    jint offset = (jint) va_arg(args, int);
    jint len = (jint) va_arg(args, int);
    const char *name = glres_cstr(jname);
    char path[256];
    if (name && glres_resolve(name, path, sizeof(path)) && len > 0) {
        FILE *f = fopen(path, "rb");
        if (f) {
            if (offset > 0) fseek(f, offset, SEEK_SET);
            jbyteArray arr = jni->NewByteArray(&jni, len);
            if (arr) {
                // SetByteArrayRegion copia; necesitamos buffer temporal.
                static jbyte chunk[65536];
                jsize done = 0;
                // Relleno por tramos para no pedir mallocs grandes aca.
                while (done < len) {
                    jsize want = len - done > (jsize)sizeof(chunk) ? (jsize)sizeof(chunk) : len - done;
                    size_t got = fread(chunk, 1, (size_t)want, f);
                    if (got == 0) break;
                    jni->SetByteArrayRegion(&jni, arr, done, (jsize)got, chunk);
                    done += (jsize)got;
                }
                // Si el archivo era mas corto, el resto queda en 0 (NewByteArray calloc).
                fclose(f);
                glres_release(jname, name);
                return arr;
            }
            fclose(f);
        }
    }
    fjni_logv_dbg("[GLResLoader] getResourceBytes(%s+%d,%d): miss", name ? name : "<null>", offset, len);
    glres_release(jname, name);
    return NULL;
}

